// Pound for Pound site: the game's heavy bag, live. Click or tap where you hit; a swipe through the bag hits harder.
// The bag is the shipped Black & Gold v2 bag (geometry generated by the game's own builder, ported), its response is
// the game's solver/dent/residual/wave/stamp maths (bag-sim.js), its look is the game shader (bag-shader.js) and its
// sound is the game's L3 punch family + RingFoley chain grains through the game's room (bag-audio.js).
//
// API (see README.md):  const bag = mountHeavyBag(container, opts)  ->  { ready: Promise, hit(damage, u, v), setMuted(b),
//                                                                         muted, dispose() }
import * as THREE from 'three';
import { buildHide, buildBagHardware, buildUpperChain, buildHookAndHoist, HOOK_PIN_Y, R as BAG_R } from './bag-geometry.js';
import * as SIM from './bag-sim.js';
import { VERT, FRAG } from './bag-shader.js';
import { BagAudio } from './bag-audio.js';

const HERE = new URL('.', import.meta.url);
const DEFAULT_BASE = new URL('../../assets/bag/', HERE).href;

// Night gym light, as an L0+L1 probe (linear): warm ring spot from above-front, cool window fill from the left/back.
const SH = { c0: [0.12, 0.11, 0.115], x: [0, 0, 0], y: [0.10, 0.085, 0.06], z: [0.03, 0.03, 0.035] };
// The boxer stands at +Z (the bag's front); the camera watches from a three-quarter spectator angle so a punch's swing
// away from the boxer reads on a flat screen (in the headset, stereo depth carries it; here, the angle has to).
const CAM_YAW = 38 * Math.PI / 180;
const PLAYER = new THREE.Vector3(0, 0, 0.75);
const REST_YAW = CAM_YAW;                                           // straps sit either side of the panel facing camera

function css(el, s) { Object.assign(el.style, s); return el; }

export function mountHeavyBag(container, opts = {}) {
  const o = Object.assign({ base: DEFAULT_BASE, lazy: true, rootMargin: '400px', readout: true, hint: true, muteButton: true,
    maxPixelRatio: 2, exposure: 1.8, waveScale: 1, onHit: null }, opts);
  if (!o.base.endsWith('/')) o.base += '/';
  let resolveReady, rejectReady;
  const api = { ready: new Promise((res, rej) => { resolveReady = res; rejectReady = rej; }), muted: false,
    hit: () => {}, setMuted: (m) => { api.muted = m; }, dispose: () => {}, _debug: {} };
  if (getComputedStyle(container).position === 'static') container.style.position = 'relative';

  let started = false;
  const start = () => { if (started) return; started = true; build().then(resolveReady, (e) => { console.error('[heavy-bag]', e); rejectReady(e); }); };
  let io = null;
  if (o.lazy && 'IntersectionObserver' in window) {
    io = new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) { io.disconnect(); io = null; start(); } }, { rootMargin: o.rootMargin });
    io.observe(container);
  } else start();
  api.dispose = () => { if (io) io.disconnect(); };
  return api;

  async function build() {
    const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
    // ---------- renderer / scene
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(o.maxPixelRatio, window.devicePixelRatio || 1));
    renderer.setClearColor(0x000000, 0);
    const canvas = renderer.domElement;
    css(canvas, { position: 'absolute', inset: '0', width: '100%', height: '100%', display: 'block', touchAction: 'pan-y',
      cursor: 'crosshair', userSelect: 'none', webkitUserSelect: 'none', webkitTapHighlightColor: 'transparent' });
    container.appendChild(canvas);
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(30, 1, 0.05, 30);

    // ---------- textures + materials
    const tl = new THREE.TextureLoader();
    const load = (n, srgb) => new Promise((res, rej) => tl.load(o.base + n, (t) => {
      t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace; t.anisotropy = Math.min(4, renderer.capabilities.getMaxAnisotropy());
      res(t); }, undefined, rej));
    const audio = new BagAudio(o.base);
    const audioReady = audio.init().catch((e) => console.warn('[heavy-bag] audio unavailable', e));
    const [alb, pack, grain] = await Promise.all([load('bag_albedo.webp', true), load('bag_pack.webp', false), load('bag_grain.webp', false)]);
    grain.wrapS = grain.wrapT = THREE.RepeatWrapping;
    const common = () => ({
      uAlb: { value: alb }, uPack: { value: pack }, uGrain: { value: grain }, uDetail: { value: 0.60 }, uExposure: { value: o.exposure },
      uSpecLeather: { value: 1.2 }, uTintA: { value: new THREE.Color(0.035, 0.035, 0.04) }, uTintB: { value: new THREE.Color(0.62, 0.46, 0.20) },
      uKeyDir: { value: new THREE.Vector3(0, 1, 0) }, uKeyCol: { value: new THREE.Vector3() },
      uSh0: { value: new THREE.Vector3(...SH.c0) }, uShX: { value: new THREE.Vector3(...SH.x) }, uShY: { value: new THREE.Vector3(...SH.y) }, uShZ: { value: new THREE.Vector3(...SH.z) },
      uMarkAo: { value: new THREE.Vector4() }, uMarkFresh: { value: new THREE.Vector4() }, uMarkN: { value: new THREE.Vector4() },
      uMarkAxis: { value: new THREE.Vector4() }, uMarkC: { value: new THREE.Vector3() },
      uImp: { value: new THREE.Vector4(0, 0, 0, -1) }, uImpB: { value: new THREE.Vector4() }, uImpC: { value: new THREE.Vector4() },
      uJolt: { value: new THREE.Vector4(0, 0, 0, -1) }, uJoltShape: { value: new THREE.Vector4(SIM.JOLT.hz, SIM.JOLT.tauS, SIM.JOLT.speed, 0) },
      uJoltSpan: { value: new THREE.Vector2(HOOK_PIN_Y, HOOK_PIN_Y + 2) },
    });
    const hideU = Object.assign(common(), {
      uDentC: { value: new THREE.Vector4(0, -999, 0, 0) }, uDentR: { value: 0.1 },
      uRes: { value: Array.from({ length: 6 }, () => new THREE.Vector4()) }, uResR: { value: new Array(6).fill(0) }, uResN: { value: 0 },
      uWaveO: { value: new THREE.Vector4(0, -999, 0, -1) }, uWaveAmp: { value: 0 },
      uWaveA: { value: new THREE.Vector4(SIM.WAVE_LIVE.speed, SIM.WAVE.PacketLenM, SIM.WAVE.DecayM, SIM.WAVE_LIVE.tau) },
      uWaveB: { value: new THREE.Vector2(SIM.WAVE.Crest > 0 ? BAG_R : BAG_R, SIM.WAVE.Crest) },
    });
    const metalU = common();
    // the jolt and key are shared: point the metal material at the hide's uniform objects
    for (const k of ['uKeyDir', 'uKeyCol', 'uJolt', 'uJoltShape', 'uJoltSpan', 'uExposure']) metalU[k] = hideU[k];
    const mk = (u, dent) => new THREE.RawShaderMaterial({ glslVersion: THREE.GLSL3, vertexShader: VERT, fragmentShader: FRAG, uniforms: u, defines: dent ? { DENT: 1 } : {} });
    const hideMat = mk(hideU, true), metalMat = mk(metalU, false);

    // ---------- the rig: pivot at the hook pin; swing (lean) -> twist -> hide + hardware; upper chain swings only
    const pivotY = HOOK_PIN_Y;
    const pivot = new THREE.Group(); pivot.position.set(0, pivotY, 0); scene.add(pivot);
    const swing = new THREE.Group(); pivot.add(swing);
    const twist = new THREE.Group(); swing.add(twist);
    const hide = new THREE.Mesh(buildHide(), hideMat); hide.position.y = -pivotY; twist.add(hide);
    const hw = new THREE.Mesh(buildBagHardware(), metalMat); hw.position.y = -pivotY; twist.add(hw);
    const upper = new THREE.Mesh(buildUpperChain(), metalMat); upper.position.y = -pivotY; swing.add(upper);
    const hook = new THREE.Mesh(buildHookAndHoist(3.2), metalMat); hook.position.y = pivotY; scene.add(hook);
    for (const m of [hide, hw, upper, hook]) m.frustumCulled = false;
    const winchY = pivotY + 3.2;
    hideU.uJoltSpan.value.set(pivotY, winchY);

    // ---------- simulation state
    const cfg = SIM.shippedConfig();
    const st = SIM.newState();
    const residual = new SIM.Residual();
    const wave = new SIM.Wave();
    let dentLocal = null;                       // contact in hide-local (three frame)
    let stamp = { remaining: 0, peak: 0, radius: 0, nLocal: new THREE.Vector3(0, 0, 1) };
    let impactAge = -1, impactStrength = 0, joltAge = -1; const joltDir = new THREE.Vector3();

    // ---------- overlay: readout, hint, mute
    const ui = css(document.createElement('div'), { position: 'absolute', inset: '0', pointerEvents: 'none', overflow: 'hidden',
      font: '600 12px/1.2 system-ui, -apple-system, "Segoe UI", sans-serif', color: '#f3e6cf' });
    container.appendChild(ui);
    const readout = css(document.createElement('div'), { position: 'absolute', left: '0', top: '0', opacity: '0', transform: 'translate(-100%,-50%)',
      textAlign: 'right', transformOrigin: '100% 50%', whiteSpace: 'nowrap', willChange: 'transform, opacity', textShadow: '0 2px 12px rgba(0,0,0,.65)' });
    readout.innerHTML = '<div data-n style="font:800 clamp(28px,4.2vw,46px)/1 system-ui,-apple-system,\'Segoe UI\',sans-serif;letter-spacing:.02em;font-variant-numeric:tabular-nums"></div>'
      + '<div data-l style="margin-top:3px;font-size:10px;letter-spacing:.28em;color:#c9a35c">DAMAGE</div>';
    if (o.readout) ui.appendChild(readout);
    const hint = css(document.createElement('div'), { position: 'absolute', left: '18px', bottom: '28px', whiteSpace: 'nowrap',
      letterSpacing: '.3em', fontSize: '13px', textShadow: '0 1px 6px rgba(0,0,0,.8)', color: 'rgba(243,230,207,.72)', transition: 'opacity .6s ease' });
    hint.textContent = matchMedia('(pointer: coarse)').matches ? 'TAP OR SWIPE THE BAG' : 'CLICK OR SWIPE THE BAG';
    if (o.hint) ui.appendChild(hint);
    const muteBtn = css(document.createElement('button'), { position: 'absolute', right: '14px', bottom: '14px', pointerEvents: 'auto',
      width: '44px', height: '44px', borderRadius: '22px', border: '1px solid rgba(243,230,207,.28)', background: 'rgba(12,10,9,.45)',
      color: '#f3e6cf', cursor: 'pointer', display: 'grid', placeItems: 'center', padding: '0', backdropFilter: 'blur(4px)' });
    const ICON_ON = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M16.5 8.5a5 5 0 0 1 0 7"/><path d="M19 6a8.5 8.5 0 0 1 0 12"/></svg>';
    const ICON_OFF = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M17 9l5 6M22 9l-5 6"/></svg>';
    const paintMute = () => { muteBtn.innerHTML = api.muted ? ICON_OFF : ICON_ON; muteBtn.setAttribute('aria-label', api.muted ? 'Unmute bag sound' : 'Mute bag sound'); muteBtn.setAttribute('aria-pressed', String(api.muted)); };
    muteBtn.type = 'button'; paintMute();
    muteBtn.addEventListener('click', (e) => { e.stopPropagation(); api.setMuted(!api.muted); audio.unlock(); });
    if (o.muteButton) ui.appendChild(muteBtn);
    api.setMuted = (m) => { api.muted = !!m; audio.setMuted(api.muted); paintMute(); };
    audio.setMuted(api.muted);

    // ---------- layout
    let W = 1, Hh = 1;
    // world Y kept in frame: the 1.52 m bag fills ~65% of the stage, centred, and its chain runs up off the top
    // (you are standing at the bag, not looking at the whole rig from across the gym)
    const framing = { lo: 0.758 - 1.17, hi: 0.758 + 1.17 };
    const camBase = new THREE.Vector3(), camTarget = new THREE.Vector3(), camRight = new THREE.Vector3(Math.cos(CAM_YAW), 0, -Math.sin(CAM_YAW));
    function layout() {
      const r = container.getBoundingClientRect();
      W = Math.max(1, r.width); Hh = Math.max(1, r.height);
      renderer.setSize(W, Hh, false);
      camera.aspect = W / Hh;
      const vfov = camera.fov * Math.PI / 180, hfov = 2 * Math.atan(Math.tan(vfov / 2) * camera.aspect);
      const hNeed = framing.hi - framing.lo, wNeed = 0.95;
      const dist = Math.max(hNeed / 2 / Math.tan(vfov / 2), wNeed / 2 / Math.tan(hfov / 2)) * 1.04;
      const cy = (framing.lo + framing.hi) / 2;
      camTarget.set(0, cy, 0);
      camBase.set(Math.sin(CAM_YAW) * dist, cy - 0.10, Math.cos(CAM_YAW) * dist);
      camera.updateProjectionMatrix();
      dirty = true;
    }
    const ro = new ResizeObserver(layout); ro.observe(container);

    // ---------- pointer
    const ndc = new THREE.Vector2(0, 0), ndcSmooth = new THREE.Vector2(0, 0);
    const trail = [];                 // recent pointer samples {t, x, y} for approach speed
    let down = false, lastHitT = -9, wasOverBag = false, lastPointerT = 0;
    const ray = new THREE.Raycaster();
    const inv = new THREE.Matrix4(), lo = new THREE.Vector3(), ld = new THREE.Vector3();
    function hitTest(cx, cy) {
      const r = canvas.getBoundingClientRect();
      const p = new THREE.Vector2(((cx - r.left) / r.width) * 2 - 1, -((cy - r.top) / r.height) * 2 + 1);
      ray.setFromCamera(p, camera);
      hide.updateWorldMatrix(true, false);
      inv.copy(hide.matrixWorld).invert();
      lo.copy(ray.ray.origin).applyMatrix4(inv); ld.copy(ray.ray.direction).transformDirection(inv);
      const Rc = BAG_R + 0.002, a = ld.x * ld.x + ld.z * ld.z, b = 2 * (lo.x * ld.x + lo.z * ld.z), c = lo.x * lo.x + lo.z * lo.z - Rc * Rc;
      const disc = b * b - 4 * a * c;
      if (a < 1e-9 || disc < 0) return null;
      const t = (-b - Math.sqrt(disc)) / (2 * a);
      if (t <= 0) return null;
      const pl = lo.clone().addScaledVector(ld, t);
      if (pl.y < 0.05 || pl.y > 1.46) return null;
      return { local: pl, world: pl.clone().applyMatrix4(hide.matrixWorld), dir: ray.ray.direction.clone() };
    }
    function speedHeightsPerS(now) {
      while (trail.length && now - trail[0].t > 110) trail.shift();
      if (trail.length < 2) return 0;
      const a = trail[0], b = trail[trail.length - 1], dt = Math.max(16, b.t - a.t);
      return Math.hypot(b.x - a.x, b.y - a.y) / Math.min(W, Hh) / (dt / 1000);   // in short-side lengths: a thumb flick across a phone counts like a mouse flick
    }
    function swipeLateral(now) {
      if (trail.length < 2) return 0;
      const a = trail[0], b = trail[trail.length - 1];
      return (b.x - a.x) / Math.max(1, Math.hypot(b.x - a.x, b.y - a.y));
    }
    function damageFor(speed) {   // a plain tap lands a solid shot (ripple and all); speed into the bag carries it up to a full 100
      const k = THREE.MathUtils.smoothstep(speed, 0.6, 4.5);
      return Math.min(100, 82 + 18 * k + (Math.random() * 8 - 4) * (1 - k));
    }
    function punchAt(h, damage, lateral) {
      // punch direction: from the boxer in front to where you hit (a side hit glances and twists), bent by the swipe
      const d = h.world.clone().sub(PLAYER); d.y = 0; d.normalize();
      if (lateral) d.addScaledVector(camRight, lateral * 0.6).normalize();
      applyHit(h.local, h.world, d, damage);
    }
    canvas.addEventListener('pointerdown', (e) => {
      const now = performance.now();
      audio.unlock();
      down = true; lastPointerT = now;
      trail.push({ t: now, x: e.clientX, y: e.clientY });
      const h = hitTest(e.clientX, e.clientY);
      wasOverBag = !!h;
      if (h) { punchAt(h, damageFor(e.pointerType === 'mouse' ? speedHeightsPerS(now) : 0), e.pointerType === 'mouse' ? swipeLateral(now) : 0); lastHitT = now; }
    });
    canvas.addEventListener('pointermove', (e) => {
      const now = performance.now();
      const r = canvas.getBoundingClientRect();
      ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
      trail.push({ t: now, x: e.clientX, y: e.clientY }); lastPointerT = now; dirty = true;
      if (!down) return;
      const h = hitTest(e.clientX, e.clientY);
      const sp = speedHeightsPerS(now);
      if (h && sp > 1.1 && now - lastHitT > 200 && (!wasOverBag || now - lastHitT > 320)) { punchAt(h, damageFor(sp), swipeLateral(now)); lastHitT = now; }
      wasOverBag = !!h;
    });
    const up = () => { down = false; };
    canvas.addEventListener('pointerup', () => audio.unlock());
    canvas.addEventListener('touchend', () => audio.unlock(), { passive: true });
    canvas.addEventListener('pointerup', up); canvas.addEventListener('pointercancel', up); canvas.addEventListener('pointerleave', up);

    // ---------- the hit (HeavyBagPresenter.ApplyCapturedPunch)
    function applyHit(local, world, dirW, damage) {
      const off = [world.x - pivot.position.x, world.y - pivot.position.y, world.z - pivot.position.z];
      SIM.apply(st, cfg, { score: damage, off, dir: [dirW.x, dirW.y, dirW.z] });
      const unit = SIM.unitForScore(cfg, damage);
      if (unit > 0) {
        dentLocal = local.clone();
        const dentR = SIM.dentRadiusFor(cfg, unit);
        residual.deposit([local.x, local.y, local.z], cfg.MaxDentM * unit, dentR);
        stamp.peak = Math.min(1, unit); stamp.remaining = SIM.MARK.fadeS;
        stamp.radius = Math.max(0.008, dentR * SIM.MARK.freshRadiusFrac * SIM.MARK.radiusScale);
        stamp.nLocal.set(local.x, 0, local.z).normalize();
        const amp = SIM.waveAmpFor(damage) * o.waveScale;
        if (amp > 0) wave.launch([local.x, local.y, local.z], amp);
        impactAge = 0; impactStrength = Math.min(1, unit);
        joltDir.set(dirW.x, 0, dirW.z).normalize().multiplyScalar(SIM.JOLT.maxM * Math.min(1, unit)); joltAge = 0;
      }
      audio.hit(damage);
      showReadout(world, damage);
      if (o.hint && hint.style.opacity !== '0') hint.style.opacity = '0';
      awakeUntil = performance.now() + 9000; dirty = true;
      const detail = { damage: Math.round(damage), unit };
      container.dispatchEvent(new CustomEvent('bag:hit', { detail }));
      if (o.onHit) o.onHit(detail);
    }
    // programmatic hit: damage 0..100; u in -1..1 sweeps the camera-facing side, v 0..1 bottom to top of the barrel
    api.hit = (damage = 80, u = 0, v = 0.6) => {
      hide.updateWorldMatrix(true, false);
      const a = CAM_YAW + u * Math.PI / 3;
      const world = new THREE.Vector3(BAG_R * Math.sin(a), 0, BAG_R * Math.cos(a));
      const axisW = new THREE.Vector3(0, 0.05 + v * 1.38, 0).applyMatrix4(hide.matrixWorld);
      world.add(axisW);
      const local = world.clone().applyMatrix4(new THREE.Matrix4().copy(hide.matrixWorld).invert());
      const dir = world.clone().sub(PLAYER); dir.y = 0; dir.normalize();
      audio.unlock(); applyHit(local, world, dir, damage);
    };

    let readoutAge = 9, readoutWorld = new THREE.Vector3();
    const nEl = readout.querySelector('[data-n]');
    function showReadout(world, damage) {
      if (!o.readout) return;
      nEl.textContent = String(Math.round(damage));
      // float beside the bag at the hit's height (camera-left), never over the dent and stamp it reports
      readoutWorld.set(0, world.y, 0).addScaledVector(camRight, -(BAG_R + 0.11)); readoutAge = 0;
    }
    function tickReadout(dt) {
      if (readoutAge > 1.2) { if (readout.style.opacity !== '0') readout.style.opacity = '0'; return; }
      readoutAge += dt;
      const p = readoutWorld.clone().project(camera);
      const x = Math.max(readout.offsetWidth + 10, (p.x * 0.5 + 0.5) * W), y = (-p.y * 0.5 + 0.5) * Hh - readoutAge * 22;
      const a = readoutAge < 0.08 ? readoutAge / 0.08 : Math.max(0, 1 - (readoutAge - 0.45) / 0.75);
      const s = 1 + 0.18 * Math.exp(-readoutAge * 14);
      readout.style.opacity = a.toFixed(3);
      readout.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) translate(-100%,-50%) scale(${s.toFixed(3)})`;
    }

    // ---------- per-frame
    const axis = new THREE.Vector3(), qSwing = new THREE.Quaternion(), UP = new THREE.Vector3(0, 1, 0);
    const keyDir = new THREE.Vector3(), tmp = new THREE.Vector3(), tmp2 = new THREE.Vector3();
    // key: the ring spot (warm, from above, leaning in from camera-left); keyAz is degrees from the camera's view, - = left
    // (low and raking so the satin sheen runs down the barrel and the dent and ripple catch it)
    const look = { exposure: o.exposure, key: 3.0, keyAz: -70, keyEl: 16 };
    let visible = true, running = false, last = 0, dirty = true, awakeUntil = performance.now() + 1500;
    let frames = 0, fpsAcc = 0, fps = 0;

    let manual = false;                          // debug: frozen clock, advanced by _debug.advance(dt) (clip capture)
    function frame(t) {
      running = false;
      if (!visible || document.hidden || manual) return;
      const dt = Math.min(0.05, Math.max(0, (t - (last || t)) / 1000)); last = t;
      // the bag keeps simulating while awake; once still and untouched it stops drawing (battery)
      if (advance(dt)) kick();
    }
    function advance(dt) {
      SIM.step(st, cfg, dt);
      residual.step(dt); wave.step(dt);
      audio.tick(st);
      const ang = SIM.resolveSwing(st, axis);
      swing.quaternion.setFromAxisAngle(axis, ang);
      twist.quaternion.setFromAxisAngle(UP, REST_YAW + st.Twist);
      // gentle cursor-follow for camera (not under reduced motion) and the key light
      ndcSmooth.lerp(ndc, 1 - Math.exp(-dt * 4));
      const par = reduceMotion.matches ? 0 : 1;
      camera.position.copy(camBase).addScaledVector(camRight, ndcSmooth.x * 0.10 * par); camera.position.y += ndcSmooth.y * 0.05 * par;
      camera.lookAt(camTarget);
      for (const k of ['c0', 'x', 'y', 'z']) hideU['uSh' + (k === 'c0' ? '0' : k.toUpperCase())].value.fromArray(SH[k]);
      for (const k of ['uSh0', 'uShX', 'uShY', 'uShZ']) metalU[k].value.copy(hideU[k].value);
      hideU.uExposure.value = look.exposure;
      { const az = CAM_YAW + (look.keyAz + ndcSmooth.x * 22) * Math.PI / 180, el = (look.keyEl + ndcSmooth.y * 8) * Math.PI / 180;
        keyDir.set(Math.sin(az) * Math.cos(el), Math.sin(el), Math.cos(az) * Math.cos(el)); }
      hideU.uKeyDir.value.copy(keyDir); hideU.uKeyCol.value.set(1.0, 0.84, 0.66).multiplyScalar(look.key);
      // presenter uniforms
      scene.updateMatrixWorld();
      const M = hide.matrixWorld;
      const depth = dentLocal ? SIM.dentDepthM(st) : 0;
      if (dentLocal) { tmp.copy(dentLocal).applyMatrix4(M); hideU.uDentC.value.set(tmp.x, tmp.y, tmp.z, depth); hideU.uMarkC.value.copy(tmp); }
      hideU.uDentR.value = SIM.dentRadiusM(st, cfg);
      let n = 0;
      for (const s of residual.s) {
        if (!s.live || s.depth < 0.0001) continue;
        tmp.set(s.c[0], s.c[1], s.c[2]).applyMatrix4(M);
        hideU.uRes.value[n].set(tmp.x, tmp.y, tmp.z, s.depth); hideU.uResR.value[n] = s.r; n++;
      }
      hideU.uResN.value = n;
      if (wave.running) { tmp.set(...wave.origin).applyMatrix4(M); hideU.uWaveO.value.set(tmp.x, tmp.y, tmp.z, wave.T); hideU.uWaveAmp.value = wave.amp; }
      else { hideU.uWaveO.value.set(0, -999, 0, -1); hideU.uWaveAmp.value = 0; }
      stamp.remaining = Math.max(0, stamp.remaining - dt);
      const op = stamp.remaining > 0 ? stamp.peak * Math.min(1, stamp.remaining / SIM.MARK.fadeS) : 0;
      const markOn = op > 0.0001;
      hideU.uMarkAo.value.set(markOn ? SIM.MARK.strength : 0, 0, SIM.MARK.warm, 0);
      hideU.uMarkFresh.value.set(op, stamp.radius, SIM.MARK.gain, markOn ? 1 : 0);
      if (dentLocal) {
        tmp2.copy(stamp.nLocal).transformDirection(M); hideU.uMarkN.value.set(tmp2.x, tmp2.y, tmp2.z, 0);
        tmp2.set(0, dentLocal.y, 0).applyMatrix4(M); hideU.uMarkAxis.value.set(tmp2.x, tmp2.y, tmp2.z, 0);
      }
      if (impactAge >= 0) { impactAge += dt; if (impactAge > SIM.IMPACT.lifeS) impactAge = -1; }
      if (dentLocal && impactAge >= 0) { tmp.copy(dentLocal).applyMatrix4(M); hideU.uImp.value.set(tmp.x, tmp.y, tmp.z, impactAge); }
      else hideU.uImp.value.w = -1;
      hideU.uImpB.value.set(impactStrength, SIM.IMPACT.riseS, SIM.IMPACT.durS, 0);
      hideU.uImpC.value.set(...SIM.IMPACT.tint, 0);
      if (joltAge >= 0) { joltAge += dt; if (joltAge >= SIM.JOLT.tauS * 6) joltAge = -1; }
      hideU.uJolt.value.set(joltDir.x, joltDir.y, joltDir.z, joltAge);
      tickReadout(dt);
      renderer.render(scene, camera);
      dirty = false;
      frames++; fpsAcc += dt; if (fpsAcc >= 1) { fps = frames / fpsAcc; frames = 0; fpsAcc = 0; }
      const moving = Math.abs(st.LeanVelX) + Math.abs(st.LeanVelZ) + Math.abs(st.TwistVel) > 1e-4 || Math.hypot(st.LeanX, st.LeanZ) > 1e-4
        || depth > 0 || n > 0 || wave.running || wave.delay > 0 || impactAge >= 0 || joltAge >= 0 || readoutAge <= 1.2
        || ndcSmooth.distanceTo(ndc) > 1e-3;
      return moving || performance.now() < awakeUntil;
    }
    function kick() { if (!running && visible && !document.hidden) { running = true; requestAnimationFrame(frame); } }
    const origDirtyKick = () => { if (!running) { last = 0; kick(); } };
    canvas.addEventListener('pointermove', origDirtyKick);
    canvas.addEventListener('pointerdown', origDirtyKick);
    const vis = new IntersectionObserver((es) => { visible = es[es.length - 1].isIntersecting; if (visible) { last = 0; kick(); } }, { rootMargin: '60px' });
    vis.observe(container);
    const onVis = () => { if (!document.hidden) { last = 0; kick(); } };
    document.addEventListener('visibilitychange', onVis);

    layout();
    renderer.compile(scene, camera);
    kick();
    await audioReady;
    container.dispatchEvent(new CustomEvent('bag:ready'));
    api._debug = { state: () => ({ fps, lean: Math.hypot(st.LeanX, st.LeanZ), twist: st.Twist, dent: st.Dent, wave: wave.T, audio: audio.ctx && audio.ctx.state }),
      st, cfg, renderer, camera, scene, audio, look, SH,
      manual: (on) => { manual = !!on; if (!on) { last = 0; kick(); } },
      advance: (dt) => advance(dt),
      frame: (type = 'image/jpeg', q = 0.88) => renderer.domElement.toDataURL(type, q) };
    api.dispose = () => {
      ro.disconnect(); vis.disconnect(); document.removeEventListener('visibilitychange', onVis);
      audio.dispose(); renderer.dispose();
      scene.traverse((m) => { if (m.geometry) m.geometry.dispose(); });
      for (const t of [alb, pack, grain]) t.dispose(); hideMat.dispose(); metalMat.dispose();
      canvas.remove(); ui.remove(); visible = false;
    };
    return api;
  }
}
